/**
 * Splits the rendered HTML of a project case study at its level-2 headings,
 * so the page template can place the architecture diagram inside the
 * "Architecture" section and render the "How to verify this" section as its
 * own block, without MDX.
 *
 * Case study bodies are plain Markdown (no images, no components): the
 * template renders this HTML with `set:html`, which skips Astro's image
 * pipeline.
 */

export interface BodySection {
  /** The heading's `id`, as generated by Astro's Markdown renderer. */
  readonly id: string;
  /** Plain text of the heading. */
  readonly heading: string;
  /** HTML of the section, starting with its `<h2>`. */
  readonly html: string;
}

export interface SplitBody {
  /** HTML before the first `<h2>`: the one-line description. */
  readonly intro: string;
  readonly sections: readonly BodySection[];
}

const H2_START = /<h2[\s>]/g;
const H2_OPEN = /^<h2\b[^>]*\bid="([^"]+)"[^>]*>([\s\S]*?)<\/h2>/;

function textOf(html: string): string {
  return html
    .replace(/<[^>]+>/g, "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .trim();
}

export function splitBody(html: string): SplitBody {
  if (html.includes("__ASTRO_IMAGE_")) {
    throw new Error("Project bodies must not contain Markdown images: put them in the template");
  }
  const starts = [...html.matchAll(H2_START)].map((match) => match.index);
  const intro = html.slice(0, starts[0] ?? html.length).trim();
  const sections = starts.map((start, index) => {
    const chunk = html.slice(start, starts[index + 1] ?? html.length).trim();
    const match = H2_OPEN.exec(chunk);
    if (!match) {
      throw new Error(`Project body heading without an id: ${chunk.slice(0, 80)}`);
    }
    return { id: match[1], heading: textOf(match[2]), html: chunk };
  });
  return { intro, sections };
}

/** The section whose heading text is `heading`, or throws: the body must have it. */
export function requireSection(body: SplitBody, heading: string, context: string): BodySection {
  const section = body.sections.find((candidate) => candidate.heading === heading);
  if (!section) {
    throw new Error(`${context}: missing the "## ${heading}" section`);
  }
  return section;
}
